'use client'

import { useState } from 'react'
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import { Badge } from "@/components/ui/badge"
import { Camera, CheckCircle2, XCircle, ArrowLeft, Utensils } from 'lucide-react'
import Link from 'next/link'

export default function ScanFoodPage() {
  const [scanning, setScanning] = useState(false)
  const [result, setResult] = useState<{ success: boolean; name: string; meal: string } | null>(null)

  const handleScan = () => {
    setScanning(true)
    // Simulate QR scan
    setTimeout(() => {
      setScanning(false)
      setResult({
        success: true,
        name: "Alex Johnson",
        meal: "Lunch"
      })
    }, 2000)
  }

  return (
    <div className="max-w-2xl mx-auto space-y-6">
      <div className="flex items-center gap-4">
        <Link href="/volunteer">
          <Button variant="ghost" size="sm" className="gap-2">
            <ArrowLeft className="h-4 w-4" />
            Back
          </Button>
        </Link>
        <div>
          <h1 className="text-3xl font-bold">Scan for Food</h1>
          <p className="text-muted-foreground">Scan participant QR to record meal</p>
        </div>
      </div>

      {/* Scanner Card */}
      <Card className="bg-card/50 backdrop-blur border-border/50">
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Utensils className="h-5 w-5 text-primary" />
            QR Code Scanner
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-6">
          {/* Camera Preview Area */}
          <div className="relative aspect-square w-full max-w-md mx-auto rounded-lg overflow-hidden bg-secondary/50 border-2 border-dashed border-border flex items-center justify-center">
            {!scanning && !result && (
              <div className="text-center space-y-4">
                <Camera className="h-16 w-16 text-muted-foreground mx-auto" />
                <p className="text-sm text-muted-foreground">Ready to scan QR code</p>
              </div>
            )}
            {scanning && (
              <div className="text-center space-y-4">
                <div className="w-16 h-16 border-4 border-primary border-t-transparent rounded-full animate-spin mx-auto" />
                <p className="text-sm text-muted-foreground">Scanning QR code...</p>
              </div>
            )}
            {result && (
              <div className="text-center space-y-4 p-8">
                {result.success ? (
                  <>
                    <CheckCircle2 className="h-16 w-16 text-green-500 mx-auto" />
                    <div className="space-y-2">
                      <p className="text-lg font-semibold">{result.name}</p>
                      <Badge variant="success" className="text-sm">
                        {result.meal} recorded
                      </Badge>
                    </div>
                  </>
                ) : (
                  <>
                    <XCircle className="h-16 w-16 text-destructive mx-auto" />
                    <p className="text-lg font-semibold text-destructive">Scan Failed</p>
                  </>
                )}
              </div>
            )}
          </div>

          {/* Action Buttons */}
          <div className="flex gap-3">
            {!result ? (
              <Button 
                onClick={handleScan} 
                disabled={scanning} 
                className="flex-1"
                size="lg"
              >
                {scanning ? "Scanning..." : "Start Scan"}
              </Button>
            ) : (
              <>
                <Button 
                  onClick={() => setResult(null)} 
                  variant="outline"
                  className="flex-1"
                  size="lg"
                >
                  Scan Another
                </Button>
                <Link href="/volunteer" className="flex-1">
                  <Button variant="default" className="w-full" size="lg">
                    Done
                  </Button>
                </Link>
              </>
            )}
          </div>
        </CardContent>
      </Card>

      {/* Meal Type Selection */}
      {!result && (
        <Card className="bg-card/50 backdrop-blur border-border/50">
          <CardHeader>
            <CardTitle className="text-base">Select Meal Type</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="grid grid-cols-3 gap-3">
              <Button variant="outline" className="h-auto py-3 flex flex-col gap-2">
                <span className="text-lg">🌅</span>
                <span className="text-sm">Breakfast</span>
              </Button>
              <Button variant="outline" className="h-auto py-3 flex flex-col gap-2 border-primary text-primary">
                <span className="text-lg">🌞</span>
                <span className="text-sm">Lunch</span>
              </Button>
              <Button variant="outline" className="h-auto py-3 flex flex-col gap-2">
                <span className="text-lg">🌙</span>
                <span className="text-sm">Dinner</span>
              </Button>
            </div>
          </CardContent>
        </Card>
      )}
    </div>
  )
}
